import { FunctionDeclaration } from '../types';
import { TOOL_RISK_REGISTRY } from '../ToolRiskRegistry';
import { SUPERPOWER_TOOLS } from '../definitions/SuperpowerTools';

export interface ToolPoolContext {
    agentId: string;
    moduleContext: string;
    isReadOnly?: boolean;
    conversationMode?: 'direct' | 'department' | 'boardroom';
}

/**
 * ToolPoolAssembler — Governance and Context Tool Filtering
 * Implements Agentic Harness Primitive #9: Tool Pool Assemblies
 * 
 * Ensures agents only receive tools appropriate for their task,
 * reducing context clutter and attack surface by preventing
 * unneeded destructive tools from being exposed.
 */
export class ToolPoolAssembler {
    /**
     * Assembles a filtered list of tools available to an agent for a specific execution.
     * 
     * @param specialistTools - The specific tools declared by the agent
     * @param context - Context including agent ID, active module, and read-only flags
     * @param maxTools - Maximum tools to return (default 24)
     * @returns Filtered list of FunctionDeclarations
     */
    static assemble(
        specialistTools: FunctionDeclaration[],
        context: ToolPoolContext,
        maxTools: number = 32
    ): FunctionDeclaration[] {

        // 1. Gather all potential tools
        const specialistToolNames = new Set(specialistTools.map(f => f.name));
        const filteredSuperpowers = SUPERPOWER_TOOLS.filter(tool => !specialistToolNames.has(tool.name));

        const collaborationToolNames = ['delegate_task', 'consult_experts', 'share_note'];
        const collaborationTools = filteredSuperpowers.filter(t => collaborationToolNames.includes(t.name));
        const otherSuperpowers = filteredSuperpowers.filter(t => !collaborationToolNames.includes(t.name));

        // Initial pool (same as legacy BaseAgent approach)
        let pool = [
            ...collaborationTools,
            ...specialistTools,
            ...otherSuperpowers
        ];

        // Avoid offering tools that the hierarchy will reject. In Boardroom,
        // managers coordinate with information notes; no peer manager executes
        // another manager's task. Direct mode is intentionally 1:1.
        if (context.conversationMode === 'boardroom') {
            pool = pool.filter(tool => !['delegate_task', 'consult_experts'].includes(tool.name));
        } else if (context.conversationMode === 'direct') {
            pool = pool.filter(tool => !collaborationToolNames.includes(tool.name));
        }

        // 2. Filter out destructive tools if in read-only mode
        if (context.isReadOnly) {
            pool = pool.filter(tool => {
                const riskTier = TOOL_RISK_REGISTRY[tool.name]?.riskTier || 'write'; // Defaults to write if unknown
                return riskTier === 'read';
            });
        }

        // 3. Module Context Filtering (Minimize attack surface)
        // If an agent is in the 'creative' module, it likely doesn't need finance tools,
        // and vice versa, unless explicitly requested as a specialist tool.
        pool = pool.filter(tool => {
            // Collaboration tools are always needed
            if (collaborationToolNames.includes(tool.name)) return true;
            // Native tools requested by the specialist are prioritized
            if (specialistToolNames.has(tool.name)) return true;

            // Filter out specific superpowers based on context mismatches to save tokens
            const name = tool.name.toLowerCase();

            // Finance/Legal tools restricted outside their domains
            if (name.includes('invoice') || name.includes('payment') || name.includes('budget')) {
                return context.moduleContext.includes('finance') || context.agentId === 'finance' || context.agentId === 'generalist';
            }

            // Heavy distribution tools
            if (name.includes('ddex') || name.includes('isrc')) {
                return context.moduleContext.includes('distribution') || context.agentId === 'distribution' || context.agentId === 'generalist';
            }

            // System-level destruction tools only allowed for admin/devops/generalist
            if (name === 'rotate_credentials') {
                return ['admin', 'devops', 'generalist'].includes(context.agentId);
            }

            return true;
        });

        // 4. Truncate to limit and return, ensuring specialist-declared tools are always preserved
        const limit = Math.max(maxTools, specialistTools.length + collaborationTools.length);
        return pool.slice(0, limit);
    }
}
'use client';
import { useEffect } from 'react';
import { useMotionValue, useSpring, motion, useTransform } from 'motion/react';

export function AnimatedNumber({
    value,
    className,
    precision = 0,
}: {
    value: number;
    className?: string;
    precision?: number;
}) {
    const motionValue = useMotionValue(0);
    const springValue = useSpring(motionValue, {
        damping: 30,
        stiffness: 100,
    });

    const displayValue = useTransform(springValue, (latest) =>
        latest.toFixed(precision)
    );

    useEffect(() => {
        motionValue.set(value);
    }, [value, motionValue]);

    return <motion.span className={className}>{displayValue}</motion.span>;
}
'use client';
import { cn } from '@/lib/utils';
import {
  AnimatePresence,
  motion,
  type TargetAndTransition,
  type Transition,
  type Variant,
  type Variants,
} from 'motion/react';
import React from 'react';

export type PresetType = 'blur' | 'fade-in-blur' | 'scale' | 'fade' | 'slide';

export type PerType = 'word' | 'char' | 'line';

export type TextEffectProps = {
  children: string;
  per?: PerType;
  as?: keyof React.JSX.IntrinsicElements;
  variants?: {
    container?: Variants;
    item?: Variants;
  };
  className?: string;
  preset?: PresetType;
  delay?: number;
  speedReveal?: number;
  speedSegment?: number;
  trigger?: boolean;
  onAnimationComplete?: () => void;
  onAnimationStart?: () => void;
  segmentWrapperClassName?: string;
  containerTransition?: Transition;
  segmentTransition?: Transition;
  style?: React.CSSProperties;
};

const defaultStaggerTimes: Record<PerType, number> = {
  char: 0.03,
  word: 0.05,
  line: 0.1,
};

const defaultContainerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05,
    },
  },
  exit: {
    transition: { staggerChildren: 0.05, staggerDirection: -1 },
  },
};

const defaultItemVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
  },
  exit: { opacity: 0 },
};

const presetVariants: Record<
  PresetType,
  { container: Variants; item: Variants }
> = {
  blur: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, filter: 'blur(12px)' },
      visible: { opacity: 1, filter: 'blur(0px)' },
      exit: { opacity: 0, filter: 'blur(12px)' },
    },
  },
  'fade-in-blur': {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, y: 20, filter: 'blur(12px)' },
      visible: { opacity: 1, y: 0, filter: 'blur(0px)' },
      exit: { opacity: 0, y: 20, filter: 'blur(12px)' },
    },
  },
  scale: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, scale: 0 },
      visible: { opacity: 1, scale: 1 },
      exit: { opacity: 0, scale: 0 },
    },
  },
  fade: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0 },
      visible: { opacity: 1 },
      exit: { opacity: 0 },
    },
  },
  slide: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, y: 20 },
      visible: { opacity: 1, y: 0 },
      exit: { opacity: 0, y: 20 },
    },
  },
};

const AnimationComponent: React.FC<{
  key?: React.Key;
  segment: string;
  variants: Variants;
  per: 'line' | 'word' | 'char';
  segmentWrapperClassName?: string;
}> = React.memo(({ segment, variants, per, segmentWrapperClassName }) => {
  const content =
    per === 'line' ? (
      <motion.span variants={variants} className='block'>
        {segment}
      </motion.span>
    ) : per === 'word' ? (
      <motion.span
        aria-hidden='true'
        variants={variants}
        className='inline-block whitespace-pre'
      >
        {segment}
      </motion.span>
    ) : (
      <motion.span className='inline-block whitespace-pre'>
        {segment.split('').map((char, charIndex) => (
          <motion.span
            key={`char-${charIndex}`}
            aria-hidden='true'
            variants={variants}
            className='inline-block whitespace-pre'
          >
            {char}
          </motion.span>
        ))}
      </motion.span>
    );

  if (!segmentWrapperClassName) {
    return content;
  }

  const defaultWrapperClassName = per === 'line' ? 'block' : 'inline-block';

  return (
    <span className={cn(defaultWrapperClassName, segmentWrapperClassName)}>
      {content}
    </span>
  );
});

AnimationComponent.displayName = 'AnimationComponent';

const splitText = (text: string, per: PerType) => {
  if (per === 'line') return text.split('\n');
  return text.split(/(\s+)/);
};

const hasTransition = (
  variant?: Variant
): variant is TargetAndTransition & { transition?: Transition } => {
  if (!variant) return false;
  return (
    typeof variant === 'object' && 'transition' in variant
  );
};

const createVariantsWithTransition = (
  baseVariants: Variants,
  transition?: Transition & { exit?: Transition }
): Variants => {
  if (!transition) return baseVariants;

  const { exit: _, ...mainTransition } = transition;

  return {
    ...baseVariants,
    visible: {
      ...baseVariants.visible,
      transition: {
        ...(hasTransition(baseVariants.visible)
          ? baseVariants.visible.transition
          : {}),
        ...mainTransition,
      },
    },
    exit: {
      ...baseVariants.exit,
      transition: {
        ...(hasTransition(baseVariants.exit)
          ? baseVariants.exit.transition
          : {}),
        ...mainTransition,
        staggerDirection: -1,
      },
    },
  };
};

export function TextEffect({
  children,
  per = 'word',
  as = 'p',
  variants,
  className,
  preset = 'fade',
  delay = 0,
  speedReveal = 1,
  speedSegment = 1,
  trigger = true,
  onAnimationComplete,
  onAnimationStart,
  segmentWrapperClassName,
  containerTransition,
  segmentTransition,
  style,
}: TextEffectProps) {
  const segments = splitText(children, per);
  const MotionTag = motion[as as keyof typeof motion] as typeof motion.div;

  const baseVariants = preset
    ? presetVariants[preset]
    : { container: defaultContainerVariants, item: defaultItemVariants };

  const stagger = defaultStaggerTimes[per] / speedReveal;

  const baseDuration = 0.3 / speedSegment;

  const customStagger = hasTransition(variants?.container?.visible ?? {})
    ? (variants?.container?.visible as TargetAndTransition).transition
        ?.staggerChildren
    : undefined;

  const customDelay = hasTransition(variants?.container?.visible ?? {})
    ? (variants?.container?.visible as TargetAndTransition).transition
        ?.delayChildren
    : undefined;

  const computedVariants = {
    container: createVariantsWithTransition(
      variants?.container || baseVariants.container,
      {
        staggerChildren: customStagger ?? stagger,
        delayChildren: customDelay ?? delay,
        ...containerTransition,
        exit: {
          staggerChildren: customStagger ?? stagger,
          staggerDirection: -1,
        },
      }
    ),
    item: createVariantsWithTransition(variants?.item || baseVariants.item, {
      duration: baseDuration,
      ...segmentTransition,
    }),
  };

  return (
    <AnimatePresence mode='popLayout'>
      {trigger && (
        <MotionTag
          initial='hidden'
          animate='visible'
          exit='exit'
          variants={computedVariants.container}
          className={className}
          onAnimationComplete={onAnimationComplete}
          onAnimationStart={onAnimationStart}
          style={style}
        >
          {per !== 'line' ? <span className='sr-only'>{children}</span> : null}
          {segments.map((segment, index) => (
            <AnimationComponent
              key={`${per}-${index}-${segment}`}
              segment={segment}
              variants={computedVariants.item}
              per={per}
              segmentWrapperClassName={segmentWrapperClassName}
            />
          ))}
        </MotionTag>
      )}
    </AnimatePresence>
  );
}

