import * as React from "react"
import { cn } from "@/lib/utils"

const TabsContext = React.createContext<{
    activeTab: string
    setActiveTab: (value: string) => void
    baseId: string
} | null>(null)

interface TabsProps extends React.HTMLAttributes<HTMLDivElement> {
    defaultValue?: string
    value?: string
    onValueChange?: (value: string) => void
}

const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(
    ({ className, defaultValue, value: controlledValue, onValueChange, children, ...props }, ref) => {
        const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue)
        const isControlled = controlledValue !== undefined
        const activeTab = (isControlled ? controlledValue : uncontrolledValue) ?? ""
        const baseId = React.useId()

        const setActiveTab = React.useCallback(
            (value: string) => {
                if (!isControlled) {
                    setUncontrolledValue(value)
                }
                onValueChange?.(value)
            },
            [isControlled, onValueChange]
        )

        return (
            <TabsContext.Provider value={{ activeTab, setActiveTab, baseId }}>
                <div ref={ref} className={cn("", className)} {...props}>
                    {children}
                </div>
            </TabsContext.Provider>
        )
    }
)
Tabs.displayName = "Tabs"

const TabsList = React.forwardRef<
    HTMLDivElement,
    React.HTMLAttributes<HTMLDivElement>
>(({ className, onKeyDown, ...props }, ref) => {
    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
        if (onKeyDown) {
            onKeyDown(e)
        }

        const list = e.currentTarget
        const tabs = Array.from(list.querySelectorAll('[role="tab"]:not([disabled])')) as HTMLElement[]
        const index = tabs.indexOf(document.activeElement as HTMLElement)

        if (index === -1) return

        let nextIndex = index

        switch (e.key) {
            case "ArrowRight":
                nextIndex = (index + 1) % tabs.length
                break
            case "ArrowLeft":
                nextIndex = (index - 1 + tabs.length) % tabs.length
                break
            case "Home":
                nextIndex = 0
                break
            case "End":
                nextIndex = tabs.length - 1
                break
            default:
                return
        }

        e.preventDefault()
        const nextTab = tabs[nextIndex]!
        nextTab.focus()
        nextTab.click()
    }

    return (
        <div
            ref={ref}
            role="tablist"
            onKeyDown={handleKeyDown}
            className={cn(
                "inline-flex h-10 items-center justify-center rounded-md bg-muted p-1 text-muted-foreground",
                className
            )}
            {...props}
        />
    )
})
TabsList.displayName = "TabsList"

const TabsTrigger = React.forwardRef<
    HTMLButtonElement,
    React.ButtonHTMLAttributes<HTMLButtonElement> & { value: string }
>(({ className, value, ...props }, ref) => {
    const context = React.useContext(TabsContext)
    if (!context) throw new Error("TabsTrigger must be used within Tabs")

    const isActive = context.activeTab === value
    const triggerId = `${context.baseId}-trigger-${value}`
    const contentId = `${context.baseId}-content-${value}`

    return (
        <button
            ref={ref}
            type="button"
            role="tab"
            aria-selected={isActive}
            aria-controls={contentId}
            id={triggerId}
            className={cn(
                "inline-flex items-center justify-center whitespace-nowrap rounded-sm px-3 py-1.5 text-sm font-medium ring-offset-background transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
                isActive
                    ? "bg-background text-foreground shadow-sm"
                    : "hover:bg-gray-800/50 hover:text-white",
                className
            )}
            onClick={() => context.setActiveTab(value)}
