                        if (e.key === 'Enter') {
                            call.end(value);
                        }
                    }}
                />
                <div className="flex justify-end gap-3">
                    <Button variant="ghost" onClick={() => call.end(null)}>
                        {cancelText}
                    </Button>
                    <Button variant="default" onClick={() => call.end(value)}>
                        {confirmText}
                    </Button>
                </div>
            </div>
        </Modal>
    );
});

