                    if (!fresh.exists || !isCurrentWorkflowStepClaim(fresh.data() as { status: string; steps: Record<string, { status: string; idempotencyKey: string }> }, stepId, idempotencyKey)) return;
                    tx.update(ref, {
                        [`steps.${stepId}.status`]: 'FAILED',
