+// ---------------------------------------------------------------------------
+// Judgment 76: Proactive Signal & Pulse Flywheel Scorer (Domain: Near-Loop Autonomy)
+// ---------------------------------------------------------------------------
+
+export type ProactiveSignalCategory =
+    | 'RELEASE_BLOCKER'
+    | 'REVENUE_ANOMALY'
+    | 'VIRAL_MOMENTUM'
+    | 'CONTRACT_DEADLINE'
+    | 'AMBIENT_NOISE';
+
+export interface ProactiveSignalInput {
+    signalId: string;
+    source: string;
+    summary: string;
+    daysUntilRelease?: number;
+    metricDeltaPct?: number;
+}
+
+export interface ProactiveSignalVerdict {
+    category: ProactiveSignalCategory;
+    isActionableNow: boolean;
+    urgencyScore: number; // 1 to 5
+    recommendedLoopTier: 'OUT_OF_LOOP_AUTO' | 'NEAR_LOOP_ONE_CLICK' | 'SUPPRESS_NOISE';
+}
+
+export function heuristicProactiveSignal(input: ProactiveSignalInput): ProactiveSignalVerdict {
+    const text = `${input.source} ${input.summary}`.toLowerCase();
+    const isBlocker = /\b(blocker|missing isrc|rejected|split|403|500|crash|unverified)\b/.test(text) ||
+        (typeof input.daysUntilRelease === 'number' && input.daysUntilRelease <= 3);
+    const isRevenue = /\b(royalty|payout|stripe|statement|clawback|discrepancy)\b/.test(text);
+    const isViral = /\b(spike|viral|trending|playlist|tiktok|surge)\b/.test(text) ||
+        (typeof input.metricDeltaPct === 'number' && input.metricDeltaPct >= 50);
+    const isContract = /\b(contract|rider|agreement|signature|escrow|deadline)\b/.test(text);
+
+    if (isBlocker) {
+        return {
+            category: 'RELEASE_BLOCKER',
+            isActionableNow: true,
+            urgencyScore: 5,
+            recommendedLoopTier: 'NEAR_LOOP_ONE_CLICK',
+        };
+    }
+    if (isRevenue) {
+        return {
+            category: 'REVENUE_ANOMALY',
+            isActionableNow: true,
+            urgencyScore: 4,
+            recommendedLoopTier: 'NEAR_LOOP_ONE_CLICK',
+        };
+    }
+    if (isContract) {
+        return {
+            category: 'CONTRACT_DEADLINE',
+            isActionableNow: true,
+            urgencyScore: 4,
+            recommendedLoopTier: 'NEAR_LOOP_ONE_CLICK',
+        };
+    }
+    if (isViral) {
+        return {
+            category: 'VIRAL_MOMENTUM',
+            isActionableNow: true,
+            urgencyScore: 3,
+            recommendedLoopTier: 'OUT_OF_LOOP_AUTO',
+        };
+    }
+    return {
+        category: 'AMBIENT_NOISE',
+        isActionableNow: false,
+        urgencyScore: 1,
+        recommendedLoopTier: 'SUPPRESS_NOISE',
+    };
+}
+
+export async function judgeProactiveSignalFlywheel(
+    input: ProactiveSignalInput
+): Promise<ProactiveSignalVerdict> {
+    const fallback = heuristicProactiveSignal(input);
+    if (!judgmentsAvailable()) {
+        return fallback;
+    }
+
+    try {
+        const functions = getFunctions();
+        const judgeFn = httpsCallable<
+            { state: Record<string, unknown>; questions: Record<string, unknown> },
+            { answers: Record<string, unknown> }
+        >(functions, 'typesafeJudge');
+
+        const result = await judgeFn({
+            state: { signal: input },
+            questions: {
+                category: {
+                    type: 'choice' as const,
+                    instructions:
+                        'Classify this incoming artist career or studio telemetry signal into the single most accurate operational category.',
+                    criteria: {
+                        RELEASE_BLOCKER: 'Missing identifiers, failed master checks, or unresolved splits blocking an upcoming release.',
+                        REVENUE_ANOMALY: 'Royalty statement discrepancy, payout hold, or financial anomaly requiring verification.',
+                        VIRAL_MOMENTUM: 'Genuine streaming velocity spike, playlist addition, or social trend worth amplifying.',
+                        CONTRACT_DEADLINE: 'Pending split signature, rider clause, or licensing deadline.',
+                        AMBIENT_NOISE: 'Routine background telemetry, hype, or low-value notification that does not need artist attention.',
+                    },
+                },
+                actionable_now: {
+                    type: 'noul' as const,
+                    instructions:
+                        'Does this signal warrant preparing a proactive draft or 1-click decision for the artist right now instead of suppressing it as background noise?',
+                },
+                urgency: {
+                    type: 'score' as const,
+                    instructions: 'Score the operational urgency of this signal from 1 (ambient info) to 5 (release-critical blocker).',
+                    criteria: [
+                        'Ambient background telemetry with no action needed.',
+                        'Low-priority update suitable for weekly digest.',
+                        'Moderate opportunity that an autonomous background agent can draft.',
+                        'High-priority business or revenue event needing near-loop 1-click approval.',
+                        'Immediate release blocker or critical production incident.',
+                    ],
+                },
+            },
+        });
+
+        const ans = result.data.answers;
+        const catRaw = ans?.category;
+        const actRaw = ans?.actionable_now;
+        const urgRaw = ans?.urgency;
+
+        const catChoice = typeof catRaw === 'string'
+            ? catRaw
+            : (typeof (catRaw as { choice?: unknown })?.choice === 'string'
+                ? (catRaw as { choice: string }).choice
+                : undefined);
+
+        const actProb = typeof actRaw === 'number'
+            ? actRaw
+            : (typeof (actRaw as { probability?: unknown })?.probability === 'number'
+                ? (actRaw as { probability: number }).probability
+                : (typeof (actRaw as { noul?: unknown })?.noul === 'number'
+                    ? (actRaw as { noul: number }).noul
+                    : undefined));
+
+        const urgScore = typeof urgRaw === 'number'
+            ? urgRaw
+            : (typeof (urgRaw as { score?: unknown })?.score === 'number'
+                ? (urgRaw as { score: number }).score
+                : undefined);
+
+        const validCategories: ProactiveSignalCategory[] = [
+            'RELEASE_BLOCKER',
+            'REVENUE_ANOMALY',
+            'VIRAL_MOMENTUM',
+            'CONTRACT_DEADLINE',
+            'AMBIENT_NOISE',
+        ];
+        const category = catChoice && (validCategories as string[]).includes(catChoice)
+            ? (catChoice as ProactiveSignalCategory)
+            : fallback.category;
+
+        const isActionableNow = typeof actProb === 'number' && Number.isFinite(actProb)
+            ? actProb >= 0.55
+            : fallback.isActionableNow;
+
+        const urgencyScore = typeof urgScore === 'number' && Number.isFinite(urgScore)
+            ? Math.round(oneIndexedScore(urgScore, fallback.urgencyScore))
+            : fallback.urgencyScore;
+
+        const recommendedLoopTier: ProactiveSignalVerdict['recommendedLoopTier'] =
+            !isActionableNow || category === 'AMBIENT_NOISE'
+                ? 'SUPPRESS_NOISE'
+                : urgencyScore >= 4 || category === 'RELEASE_BLOCKER' || category === 'REVENUE_ANOMALY' || category === 'CONTRACT_DEADLINE'
+                    ? 'NEAR_LOOP_ONE_CLICK'
+                    : 'OUT_OF_LOOP_AUTO';
+
+        return {
+            category,
+            isActionableNow,
+            urgencyScore,
+            recommendedLoopTier,
+        };
+    } catch (err: unknown) {
+        noteJudgmentFailure(err, 'proactive signal flywheel judgment');
+        return fallback;
+    }
+}
