name: Deploy to Firebase Hosting

on:
  push:
    branches:
      - main
    paths-ignore:
      - '**.md'
      - 'docs/**'
      - 'artifacts/**'
      - '.agent/**'
      - 'deep-test-*.png'
  workflow_dispatch:

concurrency:
  group: ${{ github.workflow }}-${{ github.ref }}
  # A retry may be for an older commit. Let it wait rather than cancelling the
  # current mainline deployment; otherwise a manual retry can supersede the
  # deploy that actually contains the fix.
  cancel-in-progress: ${{ github.run_attempt == '1' }}

permissions:
  contents: read
  checks: write
  pull-requests: read
  actions: read
