 */
const certify_tax_profile = wrapTool('certify_tax_profile', async (args: {
    userId: string;
    fullName?: string;
    isUsPerson: boolean;
    isEntity?: boolean;
    country: string;
    tin: string;
    signedUnderPerjury: boolean;
