const publicistRetrievalConfig = {
    'press_releases': { path: 'press_releases', requiresUserIdFilter: true },
    'email_pitches': { path: 'email_pitches', requiresUserIdFilter: true },
    'publicist_campaigns': { path: 'publicist_campaigns', requiresUserIdFilter: true },
    'publicist_contacts': { path: 'publicist_contacts', requiresUserIdFilter: true }
};
const publicistRetrievalTools = buildDomainRetrievalTools('Publicist', publicistRetrievalConfig);
const publicistRetrievalDeclarations = buildDomainRetrievalDeclarations('Publicist', publicistRetrievalConfig);

export const PublicistAgent = createAgent('publicist')
    .withName('Publicist Director')
    .withDescription('Manages public relations and media communications.')
    .withColor('bg-pink-500')
    .withCategory('manager')
    .withSystemPrompt(systemPrompt)
    .withTool({
        functionDeclarations: [{
            name: "create_campaign",
            description: "Create a new publicity campaign in the database.",
            parameters: {
                type: "OBJECT",
                properties: {
                    userId: { type: "STRING", description: "The ID of the user." },
                    title: { type: "STRING", description: "Campaign Title." },
                    artist: { type: "STRING", description: "Artist Name." },
                    type: { type: "STRING", enum: ["Album", "Single", "Tour"], description: "Type of campaign." },
                    focus: { type: "STRING", description: "Main focus or goal." }
                },
                required: ["userId", "title", "artist", "type"]
            }
        }]
    }, async (args: { userId: string, title: string, artist: string, type: 'Album' | 'Single' | 'Tour', focus: string }) => {
        /**
         * Create a new publicity campaign in the database.
         */
        try {
            const startDate = new Date().toISOString().split('T')[0];
            await PublicistService.addCampaign(args.userId, {
                title: args.title,
                artist: args.artist,
                type: args.type,
                status: 'Draft',
                releaseDate: startDate ?? new Date().toISOString().split('T')[0]!,
                progress: 0,
                openRate: 0,
                budget: 0
            });
            return {
                success: true,
                data: {
                    message: `Campaign "${args.title}" created successfully in Draft mode.`,
                    status: "Draft"
                }
            };
        } catch (error: unknown) {
            const message = error instanceof Error ? error.message : String(error);
            return { success: false, error: `Failed to create campaign: ${message}` };
        }
    })
    .withTool({
        functionDeclarations: [{
            name: "write_press_release",
            description: "Write a formal press release.",
            parameters: {
                type: "OBJECT",
                properties: {
        const totalBudget = Math.max(0, args.dailyBudgetUsd) * Math.max(1, args.durationDays);

        return toolSuccess({
            campaignId: `micro-${Date.now().toString(36)}`,
            platform: args.platform,
            dailyBudgetUsd: args.dailyBudgetUsd,
            durationDays: args.durationDays,
            totalBudgetUsd: totalBudget,
            targetAudienceProfile: args.targetAudienceProfile,
            creativeVariants: args.creativeVariants,
            status: 'ready_for_approval',
            note: 'Live ad platform credentials are not invoked from this tool. The campaign package is prepared for review/deployment.',
        }, `${args.platform} micro-campaign package prepared for ${args.durationDays} day(s) at $${args.dailyBudgetUsd}/day.`);
    }),

    deploy_email_newsletter: wrapTool('deploy_email_newsletter', async (args: {
        subjectLine: string;
        segmentName: string;
        htmlContent: string;
        sendAt?: string;
    }) => {
        return toolSuccess({
            campaignId: `email-${Date.now().toString(36)}`,
            subjectLine: args.subjectLine,
            segmentName: args.segmentName,
            htmlPreview: args.htmlContent.slice(0, 500),
            sendAt: args.sendAt || 'immediate',
            status: 'requires_email_provider_credentials',
            note: 'Provider handoff is prepared; external Mailchimp/Klaviyo send requires configured credentials.',
        }, `Newsletter "${args.subjectLine}" prepared for ${args.segmentName}; provider credentials are required before sending.`);
    }),

    generate_presave_campaign: wrapTool('generate_presave_campaign', async (args: {
        trackTitle: string;
        releaseDate: string;
        artworkUrl: string;
        collectPhoneNumbers?: boolean;
    }) => {
        const slug = args.trackTitle
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/^-|-$/g, '') || 'release';

        return toolSuccess({
            campaignId: `presave-${Date.now().toString(36)}`,
            landingPageSlug: slug,
            headline: `Pre-save ${args.trackTitle}`,
            releaseDate: args.releaseDate,
            artworkUrl: args.artworkUrl,
            fields: ['email', ...(args.collectPhoneNumbers ? ['phone'] : [])],
            callsToAction: ['Spotify Pre-save', 'Apple Music Notify', 'YouTube Reminder'],
            status: 'draft_ready',
        }, `Pre-save campaign draft generated for ${args.trackTitle}.`);
    }),

    deploy_sms_blast: wrapTool('deploy_sms_blast', async (args: {
        messageBody: string;
        segmentName: string;
        mediaUrl?: string;
    }) => {
        return toolSuccess({
            blastId: `sms-${Date.now().toString(36)}`,
            segmentName: args.segmentName,
            characterCount: args.messageBody.length,
            mediaUrl: args.mediaUrl || null,
            status: 'requires_sms_provider_credentials',
            note: 'SMS content is queued for provider handoff; Twilio credentials are required for live delivery.',
        }, `SMS blast prepared for ${args.segmentName}; Twilio credentials are required before sending.`);
    }),

    enrich_fan_data: wrapTool('enrich_fan_data', async (args: { emailAddress: string }) => {
        const domain = args.emailAddress.includes('@') ? args.emailAddress.split('@')[1] : 'unknown';
        return toolSuccess({
            emailAddress: args.emailAddress,
            domain,
            enrichmentStatus: 'local_profile_only',
            inferredSegments: domain === 'unknown' ? ['needs_cleanup'] : ['email_contact', 'owned_audience'],
            note: 'No third-party enrichment API is called without configured provider credentials.',
        }, `Fan profile enriched locally for ${args.emailAddress}.`);
    }),

    generate_influencer_bounty: wrapTool('generate_influencer_bounty', async (args: {
        trackTitle: string;
        bountyRewardUsd: number;
        soundUrl: string;
        targetInfluencerNiche?: string;
    }) => {
        return toolSuccess({
            bountyId: `bounty-${Date.now().toString(36)}`,
            trackTitle: args.trackTitle,
            rewardUsd: args.bountyRewardUsd,
            soundUrl: args.soundUrl,
            targetInfluencerNiche: args.targetInfluencerNiche || 'music discovery creators',
            referralRules: [
                'Use the official sound URL',
                'Tag the artist account',
                'Submit post URL for review',
            ],
            status: 'draft_ready',
        }, `Influencer bounty draft generated for ${args.trackTitle}.`);
    }),
