    children,
    className = '',
    ...props
}: ComponentProps<typeof DropdownMenuPrimitive.Content>) {
    return (
        <DropdownMenuPrimitive.Portal>
            <DropdownMenuPrimitive.Content
                sideOffset={6}
                align="start"
                className={`z-[120] min-w-[220px] max-h-[320px] overflow-y-auto custom-scrollbar rounded-xl border border-gray-700 bg-[#141821] p-1.5 shadow-2xl shadow-black/50 ${className}`}
                {...props}
            >
                {children}
            </DropdownMenuPrimitive.Content>
        </DropdownMenuPrimitive.Portal>
    );
}

export function DropdownMenuItem({
    children,
    className = '',
    ...props
}: ComponentProps<typeof DropdownMenuPrimitive.Item>) {
    return (
        <DropdownMenuPrimitive.Item
            className={`relative flex cursor-pointer select-none items-center gap-2.5 rounded-lg px-3 py-2 text-sm text-gray-300 outline-none transition-colors data-highlighted:bg-white/5 ${className}`}
            {...props}
        >
            {children}
        </DropdownMenuPrimitive.Item>
    );
}

export function DropdownMenuCheckboxItem({
