        const lockKey = `${context?.userId || 'unknown'}-${context?.projectId || 'unknown'}-${this.id}`;

        // Chain onto any in-flight execution for this key. The old
        // check-then-set pattern (await the held promise, THEN register your
        // own) had a check/act gap: between the held promise settling and this
        // caller registering, a fresh caller could observe no lock and start
        // executing concurrently. Chaining inside the promise body closes the
        // gap completely — every caller awaits the previous promise, and the
        // map always holds the NEWEST promise.
        const previousExecution = BaseAgent.executionLocks.get(lockKey);
        if (previousExecution) {
            logger.debug(`[BaseAgent] ${this.name} waiting for existing execution to complete...`);
        }

        const executionPromise = (async () => {
            if (previousExecution) {
                try {
                    await previousExecution;
                } catch (_err: unknown) {
                    // Previous execution failed, but we can proceed
                    logger.warn(`[BaseAgent] Previous execution failed for ${lockKey}, proceeding...`);
                }
            }
            try {
                return await this._executeInternal(task, context, onProgress, signal, attachments);
            } finally {
                // Only the NEWEST execution may release the lock — an older
                // execution finishing must not delete the key while a chained
                // successor is still queued behind it.
                if (BaseAgent.executionLocks.get(lockKey) === executionPromise) {
                    BaseAgent.executionLocks.delete(lockKey);
                }
            }
        })();

        BaseAgent.executionLocks.set(lockKey, executionPromise);
        return executionPromise;
    }

    /**
     * Stream agent response tokens in real-time via Server-Sent Events
     * Phase 2: Streaming integration for token-by-token rendering
     */
    async streamingExecute(
        task: string,
        context?: AgentContext,
        callbacks?: {
            onToken?: (token: string, index: number) => void;
            onComplete?: (response: string) => void;
            onError?: (error: Error) => void;
        }
    ): Promise<void> {
        try {
            const capabilityIntent = context?.conversationMode === 'boardroom'
                ? context.boardroomTask?.rawUserUtterance
                : task;

            if (capabilityIntent !== undefined) {
                const { isCapabilityQuestion, isDepartmentAuditOrReadinessQuestion, buildDepartmentAuditReport, buildCapabilitySummary, getCapabilityHealth } = await importWithRetry(() => import('./capabilityTruth'));
                if (isCapabilityQuestion(capabilityIntent)) {
                    let responseText = '';
                    if (isDepartmentAuditOrReadinessQuestion(capabilityIntent)) {
                        responseText = buildDepartmentAuditReport({ query: capabilityIntent });
                    } else {
                        const { loadCapabilitySnapshot } = await importWithRetry(() => import('./CapabilitySnapshotService'));
                        const { agentRegistry } = await importWithRetry(() => import('./registry'));
                        const registeredTools = (this.authorizedTools || []).filter(
                            tool => typeof this.functions?.[tool] === 'function',
                        );
                        const snapshot = await loadCapabilitySnapshot();
                        responseText = buildCapabilitySummary({
                            authorizedTools: registeredTools,
                            registeredSpecialistIds: agentRegistry.getAll().map(agent => agent.id),
                            snapshot,
                            health: getCapabilityHealth(),
                            query: capabilityIntent,
                        });
                    }
                    callbacks?.onToken?.(responseText, 0);
                    callbacks?.onComplete?.(responseText);
                    return;
                }
            }

            const streamingService = getAgentStreamingService();
            const reflectionService = getReflectionLoop();
        } catch (error) {
            const err = error instanceof Error ? error : new Error(String(error));
            callbacks?.onError?.(err);
            logger.error('[BaseAgent] Streaming execution failed', err);
        }
    }

