        let callbackReceived: ArtistMasterDirective | null = null;
        vi.mocked(onSnapshot).mockImplementationOnce(((_ref: any, onNext: (snap: any) => void) => {
            onNext({
                exists: () => true,
                data: () => ({ ...DEFAULT_ARTIST_MASTER_DIRECTIVE, artistName: 'Streaming Star' }),
