    const [newRule, setNewRule] = useState('');
    const [rawMarkdown, setRawMarkdown] = useState('');
    const [isSaving, setIsSaving] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const brandColors = useStore((state) => state.userProfile?.brandKit?.colors) ?? EMPTY_BRAND_COLORS;

    useEffect(() => {
        let isMounted = true;

        const loadDirective = async () => {
            try {
                const loaded = await artistDirectiveService.getDirective();
                if (isMounted) {
                    setDirective(loaded);
                    setRawMarkdown(compileDirectiveToMarkdown(loaded));
                    setIsLoading(false);
                }
            } catch (err) {
                logger.error('[MasterPlaybookSection] Failed to load directive:', err);
                if (isMounted) setIsLoading(false);
            }
        };

        loadDirective();

        const unsubscribe = artistDirectiveService.subscribeToDirective(undefined, (updated) => {
            if (isMounted) {
                setDirective(updated);
                setRawMarkdown(compileDirectiveToMarkdown(updated));
            }
        });

        return () => {
    DIRECTIVE_SECTION_KEYS,
    compileDirectiveToMarkdown,
    type DirectiveSectionKey,
} from '@indii/shared';
import { AnyToolFunction } from '../types';

export const read_artist_directive = wrapTool(
    'read_artist_directive',
    async (args: { sectionKey?: string }) => {
        const { sectionKey } = args;
        const directive = await artistDirectiveService.getDirective();

        if (sectionKey) {
            if (!DIRECTIVE_SECTION_KEYS.includes(sectionKey as DirectiveSectionKey)) {
                return toolError(
                    `Invalid sectionKey "${sectionKey}". Valid sections are: ${DIRECTIVE_SECTION_KEYS.join(', ')}`
                );
            }

            const section = directive.sections[sectionKey as DirectiveSectionKey];
            return toolSuccess(
                {
                    sectionKey,
                    title: section.title,
                    description: section.description,
                    content: section.content,
                    rules: section.rules,
                    updatedAt: section.updatedAt,
                },
                `Successfully loaded Artist Master Directive section "${section.title}".`
            );
        }

        const formattedMarkdown = compileDirectiveToMarkdown(directive);
        return toolSuccess(
            {
                directive,
                formattedMarkdown,
            },
            `Artist Master Directive for "${directive.artistName}" loaded successfully.`
        );
    }
);

export const refine_artist_directive = wrapTool(
    'refine_artist_directive',
    async (args: {
        sectionKey: string;
        ruleOrContent: string;
        action: 'add_rule' | 'remove_rule' | 'set_content';
        reason?: string;
        } catch (err) {
            logger.warn('[BrandSyncService] Failed to dispatch update event:', err);
        }
    }

    /**
     * Cascades the brand palette to the living Artist Master Directive
     * under the 'brandingAesthetics' section.
     */
    async syncToArtistDirective(
        palette: BrandColorItem[],
        aestheticStyle?: string,
        reason: string = 'Brand color palette updated'
    ): Promise<boolean> {
        try {
            const paletteSummary = palette.map(p => p.raw).join(', ');
            const directive = await artistDirectiveService.getDirective();
            const currentRules = directive.sections.brandingAesthetics?.rules || [];

            // Remove previous brand color palette rule if present
            const filteredRules = currentRules.filter(
                r => !r.toLowerCase().startsWith('brand color palette:')
            );

            // Create fresh authoritative palette rule
            const newPaletteRule = `Brand Color Palette: ${paletteSummary}`;
            const updatedRules = [...filteredRules, newPaletteRule];

            if (aestheticStyle?.trim()) {
                const filteredStyleRules = updatedRules.filter(
                    r => !r.toLowerCase().startsWith('visual aesthetic style:')
                );
                filteredStyleRules.push(`Visual Aesthetic Style: ${aestheticStyle.trim()}`);
                updatedRules.length = 0;
                updatedRules.push(...filteredStyleRules);
            }

