        update[`steps.${stepId}.completedAt`] = admin.firestore.FieldValue.delete();
        update[`steps.${stepId}.idempotencyKey`] = randomUUID();
      }
      tx.update(ref, update as admin.firestore.UpdateData<admin.firestore.DocumentData>);
    });
