// Judgment 56: DDEX genre & cultural subculture classification (Domain: Distribution & Ingestion)
// ---------------------------------------------------------------------------

export type DdexPrimaryGenre =
    | 'Electronic'
    | 'Hip-Hop/Rap'
    | 'Alternative Rock'
    | 'R&B/Soul'

