'use client';
import { useEffect } from 'react';
import { useMotionValue, useSpring, motion, useTransform, useReducedMotion } from 'motion/react';

export function AnimatedNumber({
    value,
    className,
    precision = 0,
}: {
    value: number;
    className?: string;
    precision?: number;
}) {
    const reducedMotion = useReducedMotion();
    const safePrecision = Number.isFinite(precision) ? Math.max(0, Math.min(6, Math.trunc(precision))) : 0;
    const finiteValue = Number.isFinite(value) ? value : null;
    const accessibleValue = finiteValue === null ? '—' : finiteValue.toFixed(safePrecision);
    const motionValue = useMotionValue(0);
    const springValue = useSpring(motionValue, {
        damping: 30,
        stiffness: 100,
    });

    const displayValue = useTransform(springValue, (latest) =>
        latest.toFixed(safePrecision)
    );

    useEffect(() => {
        if (finiteValue !== null) motionValue.set(finiteValue);
    }, [finiteValue, motionValue]);

    if (reducedMotion || finiteValue === null) {
        return <span className={className}>{accessibleValue}</span>;
    }

    return <span className={className}>
        <span className="sr-only">{accessibleValue}</span>
        <motion.span aria-hidden="true">{displayValue}</motion.span>
    </span>;
}
import React from 'react';
import { render, screen } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { AnimatedNumber } from './animated-number';

const reducedMotion = vi.hoisted(() => vi.fn(() => false));
vi.mock('motion/react', async (importOriginal) => ({
    ...(await importOriginal<typeof import('motion/react')>()),
    useReducedMotion: reducedMotion,
}));

describe('AnimatedNumber', () => {
    beforeEach(() => reducedMotion.mockReturnValue(false));

    it('announces the final value while hiding the animated frames', () => {
        const { rerender } = render(<AnimatedNumber value={12.34} precision={1} />);
        expect(screen.getByText('12.3')).toHaveClass('sr-only');
        expect(screen.getByText('12.3').nextElementSibling).toHaveAttribute('aria-hidden', 'true');
        rerender(<AnimatedNumber value={20.56} precision={1} />);
        expect(screen.getByText('20.6')).toHaveClass('sr-only');
    });

    it('shows a stable value without animation when reduced motion is requested', () => {
        reducedMotion.mockReturnValue(true);
        render(<AnimatedNumber value={24.5} precision={1} />);
        expect(screen.getByText('24.5')).not.toHaveClass('sr-only');
    });

    it.each([Number.NaN, Infinity, -Infinity])('shows an unavailable value for nonfinite input (%s)', value => {
        render(<AnimatedNumber value={value} />);
        expect(screen.getByText('—')).toBeInTheDocument();
    });

    it('clamps invalid precision instead of throwing', () => {
        reducedMotion.mockReturnValue(true);
        const { rerender } = render(<AnimatedNumber value={1.23456789} precision={100} />);
        expect(screen.getByText('1.234568')).toBeInTheDocument();
        rerender(<AnimatedNumber value={1.23456789} precision={Number.NaN} />);
        expect(screen.getByText('1')).toBeInTheDocument();
    });
});
'use client';
import { cn } from '@/lib/utils';
import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type TargetAndTransition,
  type Transition,
  type Variant,
  type Variants,
} from 'motion/react';
import React from 'react';

export type PresetType = 'blur' | 'fade-in-blur' | 'scale' | 'fade' | 'slide';

export type PerType = 'word' | 'char' | 'line';

export type TextEffectProps = {
  children: string;
  per?: PerType;
  as?: keyof React.JSX.IntrinsicElements;
  variants?: {
    container?: Variants;
    item?: Variants;
  };
  className?: string;
  preset?: PresetType;
  delay?: number;
  speedReveal?: number;
  speedSegment?: number;
  trigger?: boolean;
  onAnimationComplete?: () => void;
  onAnimationStart?: () => void;
  segmentWrapperClassName?: string;
  containerTransition?: Transition;
  segmentTransition?: Transition;
  style?: React.CSSProperties;
};

const defaultStaggerTimes: Record<PerType, number> = {
  char: 0.03,
  word: 0.05,
  line: 0.1,
};

const defaultContainerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05,
    },
  },
  exit: {
    transition: { staggerChildren: 0.05, staggerDirection: -1 },
  },
};

const defaultItemVariants: Variants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
  },
  exit: { opacity: 0 },
};

const presetVariants: Record<
  PresetType,
  { container: Variants; item: Variants }
> = {
  blur: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, filter: 'blur(12px)' },
      visible: { opacity: 1, filter: 'blur(0px)' },
      exit: { opacity: 0, filter: 'blur(12px)' },
    },
  },
  'fade-in-blur': {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, y: 20, filter: 'blur(12px)' },
      visible: { opacity: 1, y: 0, filter: 'blur(0px)' },
      exit: { opacity: 0, y: 20, filter: 'blur(12px)' },
    },
  },
  scale: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, scale: 0 },
      visible: { opacity: 1, scale: 1 },
      exit: { opacity: 0, scale: 0 },
    },
  },
  fade: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0 },
      visible: { opacity: 1 },
      exit: { opacity: 0 },
    },
  },
  slide: {
    container: defaultContainerVariants,
    item: {
      hidden: { opacity: 0, y: 20 },
      visible: { opacity: 1, y: 0 },
      exit: { opacity: 0, y: 20 },
    },
  },
};

const AnimationComponent: React.FC<{
  key?: React.Key;
  segment: string;
  variants: Variants;
  per: 'line' | 'word' | 'char';
  segmentWrapperClassName?: string;
}> = React.memo(({ segment, variants, per, segmentWrapperClassName }) => {
  const content =
    per === 'line' ? (
      <motion.span variants={variants} className='block'>
        {segment}
      </motion.span>
    ) : per === 'word' ? (
      <motion.span
        aria-hidden='true'
        variants={variants}
        className='inline-block whitespace-pre'
      >
        {segment}
      </motion.span>
    ) : (
      <motion.span variants={variants} className='inline-block whitespace-pre'>
        {segment}
      </motion.span>
    );

  if (!segmentWrapperClassName) {
    return content;
  }

  const defaultWrapperClassName = per === 'line' ? 'block' : 'inline-block';

  return (
    <span className={cn(defaultWrapperClassName, segmentWrapperClassName)}>
      {content}
    </span>
  );
});

AnimationComponent.displayName = 'AnimationComponent';

const splitText = (text: string, per: PerType) => {
  if (per === 'line') return text.split('\n');
  if (per === 'char') {
    if (typeof Intl.Segmenter === 'function') {
      return Array.from(new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text), part => part.segment);
    }
    return Array.from(text);
  }
  return text.split(/(\s+)/);
};

const hasTransition = (
  variant?: Variant
): variant is TargetAndTransition & { transition?: Transition } => {
  if (!variant) return false;
  return (
    typeof variant === 'object' && 'transition' in variant
  );
};

const createVariantsWithTransition = (
  baseVariants: Variants,
  transition?: Transition & { exit?: Transition }
): Variants => {
  if (!transition) return baseVariants;

  const { exit: _, ...mainTransition } = transition;

  return {
    ...baseVariants,
    visible: {
      ...baseVariants.visible,
      transition: {
        ...(hasTransition(baseVariants.visible)
          ? baseVariants.visible.transition
          : {}),
        ...mainTransition,
      },
    },
    exit: {
      ...baseVariants.exit,
      transition: {
        ...(hasTransition(baseVariants.exit)
          ? baseVariants.exit.transition
          : {}),
        ...mainTransition,
        staggerDirection: -1,
      },
    },
  };
};

export function TextEffect({
  children,
  per = 'word',
  as = 'p',
  variants,
  className,
  preset = 'fade',
  delay = 0,
  speedReveal = 1,
  speedSegment = 1,
  trigger = true,
  onAnimationComplete,
  onAnimationStart,
  segmentWrapperClassName,
  containerTransition,
  segmentTransition,
  style,
}: TextEffectProps) {
  const reducedMotion = useReducedMotion();
  const segments = splitText(children, per);
  const MotionTag = motion[as as keyof typeof motion] as typeof motion.div;

  const baseVariants = preset
    ? presetVariants[preset]
    : { container: defaultContainerVariants, item: defaultItemVariants };

  const stagger = defaultStaggerTimes[per] / speedReveal;

  const baseDuration = 0.3 / speedSegment;

  const customStagger = hasTransition(variants?.container?.visible ?? {})
    ? (variants?.container?.visible as TargetAndTransition).transition
        ?.staggerChildren
    : undefined;

  const customDelay = hasTransition(variants?.container?.visible ?? {})
    ? (variants?.container?.visible as TargetAndTransition).transition
        ?.delayChildren
    : undefined;

  const computedVariants = {
    container: createVariantsWithTransition(
      variants?.container || baseVariants.container,
      {
        staggerChildren: customStagger ?? stagger,
        delayChildren: customDelay ?? delay,
        ...containerTransition,
        exit: {
          staggerChildren: customStagger ?? stagger,
          staggerDirection: -1,
        },
      }
    ),
    item: createVariantsWithTransition(variants?.item || baseVariants.item, {
      duration: baseDuration,
      ...segmentTransition,
    }),
  };

  if (reducedMotion) {
    return trigger ? React.createElement(as, { className, style }, children) : null;
  }

  return (
    <AnimatePresence mode='popLayout'>
      {trigger && (
        <MotionTag
          initial='hidden'
          animate='visible'
          exit='exit'
          variants={computedVariants.container}
          className={className}
          onAnimationComplete={onAnimationComplete}
          onAnimationStart={onAnimationStart}
          style={style}
import React from 'react';
import { render, screen } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { TextEffect } from './text-effect';

const reducedMotion = vi.hoisted(() => vi.fn(() => false));
vi.mock('motion/react', async importOriginal => ({
  ...(await importOriginal<typeof import('motion/react')>()),
  useReducedMotion: reducedMotion,
}));

describe('TextEffect', () => {
  beforeEach(() => reducedMotion.mockReturnValue(false));

  it('announces multiline text once and hides visual line segments', () => {
    const value = 'First line\nSecond line';
    const { container } = render(<TextEffect per='line'>{value}</TextEffect>);
    expect(container.querySelector('.sr-only')?.textContent).toBe(value);
    expect(container.querySelector('[aria-hidden="true"]')).toHaveTextContent('First lineSecond line');
  });

  it('keeps emoji and combining marks as whole animated characters', () => {
    const { container } = render(<TextEffect per='char'>A👩🏽‍🎤é</TextEffect>);
    const segments = Array.from(container.querySelectorAll('[aria-hidden="true"] > span'));
    expect(segments.map(segment => segment.textContent)).toEqual(['A', '👩🏽‍🎤', 'é']);
  });

  it('shows plain text with no hidden animation under reduced motion', () => {
    reducedMotion.mockReturnValue(true);
    const { container } = render(<TextEffect as='h2' per='char'>Artist updates</TextEffect>);
    expect(screen.getByRole('heading', { name: 'Artist updates' })).toBeInTheDocument();
    expect(container.querySelector('[aria-hidden="true"]')).not.toBeInTheDocument();
    expect(container.querySelector('.sr-only')).not.toBeInTheDocument();
  });
});

